Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.util.*;
import java.lang.*;
import java.io.*;

public class Codechef {
    public static void main(String[] args) throws Exception {
        Scanner sc = new Scanner(System.in);
        sc.nextLine();
        String st = sc.nextLine();

        List<String> outsideParts = new ArrayList<>();
        List<String> insideParts = new ArrayList<>();

        int i = 0;
        int j = 0;

        while (i < st.lastIndexOf(')')) {
            int open = st.indexOf('(', i);
            outsideParts.add(st.substring(j, open));

            j = st.indexOf(')', j + 1) + 1;
            int close = st.indexOf(')', i + 1);
            insideParts.add(st.substring(open + 1, close));

            i = close;
        }

        outsideParts.add(st.substring(j));

        int maxl = 0;
        int cnt = 0;

        for (String part : outsideParts) {
            StringTokenizer tok = new StringTokenizer(part, "_");
            while (tok.hasMoreTokens()) {
                int l = tok.nextToken().length();
                if (l > maxl) {
                    maxl = l;
                }
            }
        }

        for (String part : insideParts) {
            StringTokenizer tok = new StringTokenizer(part, "_");
            while (tok.hasMoreTokens()) {
                tok.nextToken();
                cnt++;
            }
        }

        System.out.println(maxl + " " + cnt);
    }
}
